DC1      CSECT
         PRINT DATA
* character
         DC    C'ABC'
         DC    CL5'ABC'
         DC    CL2'ABCDEF'
         DC    C'a b ^ [ ] ! | { } \ ~ ` @ # $'
         DC    2C'AB'
         DC    CL0'A'
         DC    C'A''B&&C'
         DC    CU'AB'
         DC    CA'AB'
         DC    CE'AB'
* hex, binary
         DC    X'123'
         DC    XL4'12'
         DC    XL1'1234'
         DC    X'12',X'3456'
         DC    B'101'
         DC    BL2'1'
         DC    B'111111111'
         DC    3X'FF'
* fixed point
         DC    H'1,-1,32767'
         DC    H'65535'
         DC    F'100,-100'
         DC    FD'1'
         DC    FD'-1'
         DC    HL1'-1'
         DC    FL3'5'
         DC    FL5'-5'
         DC    FS8'3'
         DC    F'1.5'
         DC    F'1E2'
         DC    F'1.5E1'
         DC    FL4'3.99'
         DC    H'-1.5'
         DC    HL.4'3'
         DC    XL.4'3'
         DC    BL.3'101'
* packed, zoned
         DC    P'123'
         DC    P'-123'
         DC    P'+0'
         DC    PL4'12'
         DC    PL2'12345'
         DC    P'1.5'
         DC    Z'123'
         DC    Z'-123'
         DC    ZL5'12'
         DC    P'1,2,3'
         DC    P'12345678901234567890123456789012'
* addresses
         DC    A(*)
         DC    A(X'10')
         DC    AL2(5)
         DC    AL3(5)
         DC    AL1(5)
         DC    A(L1,L1+4)
         DC    Y(L1)
         DC    S(L1)
         DC    A(L1-DC1)
         DC    AD(L1)
         DC    AD(5)
         DC    V(EXT1)
         DC    VL3(EXT1)
         DC    Q(DC1)
L1       DC    A(0)
         EXTRN EXT1
         END
